import{_ as e,o as c,c as t,a5 as d}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"二、运算符","description":"","frontmatter":{"title":"二、运算符","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/二、运算符.md","filePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/二、运算符.md"}'),p={name:"posts/java快速入门/第一部分：语言基础/01-基础语法/二、运算符.md"};function n(r,o,s,i,a,g){return c(),t("div",null,[...o[0]||(o[0]=[d("<div><p><strong>包括</strong></p><ol><li><strong>算术运算符</strong></li><li><strong>赋值运算符</strong></li><li><strong>比较运算符</strong></li><li><strong>逻辑运算符</strong></li><li><strong>三元运算符</strong><strong>算术运算符包括：</strong><code>+</code> 加法运算，字符串连接运算</li></ol><p><code>-</code></p><p>减法运算</p><p><code>*</code></p><p>乘法运算</p><p><code>/</code></p><p>除法运算</p><p><code>%</code></p><p>取模运算，两个数字相除取余数</p><p><code>++</code></p><p>、 <code>--</code> 自增自减运算</p><p><code>Java</code>中，整数使用以上运算符，无论怎么计算，也不会得到小数。</p><p>public static void main(String[] args) { int i = 1234; System.out.println(i/1000*1000);// 计算结果是</p><p>1000 } ++ <strong>运算，变量自己增长</strong><code>1</code>。反之， <code>--</code> 运算，变量自己减少<code>1</code>，用法与 <code>++</code> 一致。 <strong>独立运算：</strong> 变量在独立运算时， 前<code>++</code> 和 后<code>++</code> 没有区别 。 变量 前<code>++</code> ：例如 <code>++i</code> 变量 后<code>++</code> ：例如</p><p><code>i++</code></p><p><strong>混合运算：</strong> 和其他变量放在一起， 前<code>++</code> 和 后<code>++</code> 就产生了不同。 变量 前<code>++</code> ：变量<code>a</code>自己加<code>1</code>，将加<code>1</code>后的结果赋值给<code>b</code>，也就是说<code>a</code>先计算。</p><p>public static void main(String[] args) { int a = 1; int b = ++a; System.out.println(a);// 计算结果是</p><p>2 System.out.println(b);// 计算结果是</p><p>2 } 变量 后<code>++</code> ：变量<code>a</code>先把自己的值<code>1</code>，赋值给变量<code>b</code>，此时变量<code>b</code>的值就是<code>1</code>，变量<code>a</code>自己再加<code>1</code>。</p><p>public static void main(String[] args) { int a = 1; int b = a++; System.out.println(a);// 计算结果是</p><p>2 System.out.println(b);// 计算结果是</p><p>1 }</p><p><code>+</code> <strong>符号在字符串中的操作：</strong><code>+</code> 符号在遇到字符串的时候，表示<strong>连接、拼接</strong>的含义。</p><p><code>&quot;a&quot;+&quot;b&quot;</code></p><p>的结果是“<code>ab</code>”，连接含义</p><p>public static void main(String[] args){ System.out.println(&quot;5+5=&quot;+5+5);// 输出</p><p>5+5=55 } <strong>赋值运算符包括：</strong></p><p><code>=</code></p><p>等于号</p><p><code>+=</code></p><p>加等于</p><p><code>-=</code></p><p>减等于</p><p><code>*=</code></p><p>乘等于</p><p><code>/=</code></p><p>除等于</p><p><code>%=</code></p><p>取模等 赋值运算符，就是将符号右边的值，赋给左边的变量。</p><p>public static void main(String[] args){ int i = 5; i+=5;// 计算方式 <code>i=i+5</code> 变量<code>i</code>先加<code>5</code>，再赋值变量</p><p>i System.out.println(i); // 输出结果是</p><p>10 }</p><p><strong>比较运算符包括：</strong></p><p><code>==</code></p><p>比较符号两边数据是否相等，相等结果是<code>true</code>。</p><p><code>\\&lt;</code></p><p>比较符号左边的数据是否小于右边的数据，如果小于结果是<code>true</code>。</p><p><code>\\&gt;</code></p><p>比较符号左边的数据是否大于右边的数据，如果大于结果是<code>true</code>。</p><p><code>\\&lt;=</code></p><p>比较符号左边的数据是否小于或者等于右边的数据，如果小于结果是<code>true</code>。</p><p><code>\\&gt;=</code></p><p>比较符号左边的数据是否大于或者等于右边的数据，如果小于结果是<code>true</code>。 ！<code>=</code> 不等于符号 ，如果符号两边的数据不相等，结果是<code>true</code>。 比较运算符，是两个数据之间进行比较的运算，运算结果都是布尔值 <code>true</code> 或者 <code>false</code> 。</p><p>public static void main(String[] args) { System.out.println(1==1);//true System.out.println(1&lt;2);//true System.out.println(3&gt;4);//false System.out.println(3&lt;=4);//true System.out.println(3&gt;=4);//false System.out.println(3!=4);//true } <strong>逻辑运算符包括：</strong></p><p><strong>三元运算符格式：</strong> 数据类型 变量名</p><p><code>=</code></p><p>布尔类型表达式？结果<code>1</code>：结果<code>2</code> 三元运算符计算方式： 布尔类型表达式结果是<code>true</code>，三元运算符整体结果为结果<code>1</code>，赋值给变量。 布尔类型表达式结果是<code>false</code>，三元运算符整体结果为结果<code>2</code>，赋值给变量。</p></div>",1)])])}const m=e(p,[["render",n]]);export{u as __pageData,m as default};
